cd /testbed && python - <<'PY'
import numpy as np
for dt in [np.int64, np.float64, np.float32]:
    x = np.array(1, dtype=dt)
    try:
        y = np.nextafter(x, np.inf)
        print(dt, y, y.dtype)
    except Exception as e:
        print(dt, 'err', type(e), e)
PY

